{"id": "lastu-bimalik", "kb": 1, "sourceType": "sunnah", "mainCategory": "العلاقات", "sourceStrength": "موثق", "seerahSources": [], "title": "«هوّن عليك، فإني لست بملك»: طمأنة من يرتجف أمامك", "eventDescription": "جاء رجل يكلّم النبي ﷺ فأخذته الرهبة حتى جعلت ترتعد فرائصه، فقال له النبي ﷺ: «هوّن عليك، فإني لست بملك، إنما أنا ابن امرأة تأكل القديد»، أي اللحم المجفف الذي يأكله عامة الناس.", "historicalContext": "في المدينة، والنبي ﷺ قائد الأمة ومهابته عظيمة في القلوب. والحديث صححه الألباني، وضعفه بعض المحققين.", "problemType": "إنسان يرتجف من الرهبة أمام صاحب مكانة، فلا يستطيع أن يتكلم", "responseType": "تطمين فوري بكلمات تُنزل المكانة إلى مستوى البشر، وتذكير بالأصل المتواضع", "reflection": "أعظم البشر قال لمن يرتجف أمامه: «هوّن عليك». إن كان أحد يخافك، فهل ترى خوفه وتطمئنه؟ وإن كنت تخاف أحدًا، فتذكر أنه ابن امرأة مثلك.", "subCategories": ["الرهبة والخوف", "التواضع", "تطمين الآخرين"], "participants": ["النبي ﷺ", "رجل جاء يكلّمه"], "prophetTraits": ["التواضع", "الرحمة", "حسن الخلق"], "emotionsAddressed": ["الرهبة والخوف من صاحب المكانة", "القلق عند الحديث", "الشعور بالصغر"], "principles": ["المكانة العالية تقتضي تواضعًا أكبر", "تطمين الخائف يبدأ بإزالة الحواجز", "ذكر الأصل البسيط يقرّب ولا يُنقص", "لا ينبغي أن يرتجف إنسان أمام إنسان"], "modernApplications": ["إذا كنت مديرًا أو أبًا أو معلمًا يهابك من تحتك، فابدأ بطمأنتهم", "إذا كنت تخاف من الحديث مع صاحب مكانة، فتذكر أنه إنسان مثلك", "لا تستخدم مكانتك لإخافة الناس", "اذكر بساطة أصلك لمن يراك أعلى منه"], "notToApplyTo": ["لا يعني التواضع إلغاء الاحترام والحدود في العمل", "ولا أن تخفي مسؤوليتك أو تتهرب منها بحجة التواضع"], "keywords": ["أخاف من مديري", "أرتجف عند الكلام مع المسؤول", "رهبة من الكبار", "قلق اجتماعي", "ابني يخاف مني", "الموظفون يخافون مني"], "semanticTags": ["تواضع", "رهبة", "طمأنينة", "قلق", "قيادة"], "behaviorObservations": ["لاحظ خوف الرجل فورًا", "بدأ بالتطمين قبل أي كلام آخر", "نفى عن نفسه صفة الملك المتسلط", "ذكّر بأصله البسيط ليقرّب المسافة"], "whatToAvoid": ["الاستمتاع بخوف الناس منك", "تجاهل ارتباك من يحدثك"], "quranRefs": [{"surahName": "الشعراء", "ayahNumber": 215, "text": "واخفض جناحك لمن اتبعك من المؤمنين", "context": "أمر للنبي ﷺ بالتواضع واللين مع المؤمنين", "relevance": "التواضع مع من يهابك يزيل الخوف ويفتح القلوب"}], "hadithRefs": [{"text": "أتى النبي ـ ﷺ ـ رجل فكلمه فجعل ترعد فرائصه فقال له هون عليك فإني لست بملك إنما أنا ابن امرأة تأكل القديد", "narrator": "أبو مسعود البدري رضي الله عنه", "source": "ابن ماجه (3312)", "grade": "صحيح"}]},
{"id": "badr-dua", "kb": 1, "sourceType": "sunnah", "mainCategory": "القرارات الصعبة", "sourceStrength": "موثق بدرجة عالية", "seerahSources": ["السيرة النبوية لابن هشام"], "title": "ليلة بدر: الإلحاح في الدعاء بعد إتمام الأسباب", "eventDescription": "يوم بدر نظر النبي ﷺ إلى المشركين وهم ألف، وأصحابه ثلاثمائة وتسعة عشر رجلًا. وكان قد رتّب الصفوف واستشار أصحابه، ثم استقبل القبلة ومد يديه يهتف بربه: «اللهم أنجز لي ما وعدتني، اللهم آت ما وعدتني...»، وظل يدعو حتى سقط رداؤه عن منكبيه، فأتاه أبو بكر فرده عليه والتزمه من ورائه يطمئنه. فنزل قوله تعالى: ﴿إذ تستغيثون ربكم فاستجاب لكم﴾.", "historicalContext": "في السنة الثانية للهجرة، أول مواجهة كبرى بين المسلمين وقريش، مع فارق كبير في العدد والعدة.", "problemType": "مواجهة مصيرية مع فارق كبير في القوة، وقلق على مصير الجماعة كلها", "responseType": "إتمام الاستعداد العملي، ثم الإلحاح في الدعاء بكل القلب", "reflection": "النبي ﷺ أعدّ كل شيء، ثم دعا حتى سقط رداؤه. افعل ما تستطيع، ثم ارفع يديك بصدق؛ فهذا ليس ضعفًا بل اكتمال للتوكل.", "subCategories": ["الخوف قبل المواجهة", "الأخذ بالأسباب", "الدعاء"], "participants": ["النبي ﷺ", "أبو بكر الصديق رضي الله عنه", "الصحابة رضي الله عنهم"], "prophetTraits": ["التوكل مع الأخذ بالأسباب", "الشورى", "الصدق مع المشاعر", "الرجاء"], "emotionsAddressed": ["القلق قبل حدث مصيري", "الخوف من الفشل", "الشعور بقلة الحيلة"], "principles": ["الأخذ بالأسباب ثم التوكل، لا أحدهما دون الآخر", "الإلحاح في الدعاء ليس ضعفًا بل صدق", "إظهار القلق لله أمام الآخرين لا يعيب القائد", "الصديق الحقيقي يطمئنك في لحظة شدتك"], "modernApplications": ["قبل امتحان أو مقابلة أو عملية: استعد جيدًا، ثم ألحّ في الدعاء", "لا تخجل من قلقك قبل الحدث الكبير؛ حتى النبي ﷺ استغاث بربه", "كن مثل أبي بكر لصديقك القلق: قريبًا منه تطمئنه", "بعد أن تفعل ما عليك، اترك النتيجة لله"], "notToApplyTo": ["لا يعني هذا الاكتفاء بالدعاء دون استعداد", "ولا أن كل نتيجة ستأتي كما تتمنى في الدنيا"], "keywords": ["قلق قبل الامتحان", "خائف من مقابلة العمل", "عندي عملية جراحية غدا", "المهمة أكبر مني", "الفرق كبير بيني وبين المنافسين", "أدعو كثيرا قبل الحدث"], "semanticTags": ["دعاء", "أسباب", "قلق", "توكل", "مواجهة"], "behaviorObservations": ["استعد عمليًا ورتّب الصفوف قبل الدعاء", "استقبل القبلة ومد يديه وألحّ في الدعاء", "لم يخفِ قلقه وتضرعه عن أصحابه", "قبِل تطمين أبي بكر رضي الله عنه"], "whatToAvoid": ["ترك الاستعداد اعتمادًا على الدعاء", "إخفاء القلق وإظهار ثقة زائفة"], "quranRefs": [{"surahName": "الأنفال", "ayahNumber": 9, "text": "إذ تستغيثون ربكم فاستجاب لكم أني ممدكم بألف من الملائكة مردفين", "context": "نزلت في استغاثة النبي ﷺ والمؤمنين يوم بدر", "relevance": "الاستغاثة الصادقة في لحظة الخوف تُستجاب"}], "hadithRefs": [{"text": "نظر رسول الله ﷺ إلى المشركين وهم ألف وأصحابه ثلاثمائة وتسعة عشر رجلا فاستقبل نبي الله ﷺ القبلة ثم مد يديه فجعل يهتف بربه اللهم أنجز لي ما وعدتني اللهم آت ما وعدتني اللهم إن تهلك هذه العصابة من أهل الإسلام لا تعبد في الأرض. فمازال يهتف بربه مادا يديه مستقبل القبلة حتى سقط رداؤه عن منكبيه فأتاه أبو بكر فأخذ رداءه فألقاه على منكبيه", "narrator": "عمر بن الخطاب رضي الله عنه", "source": "مسلم (1763)", "grade": "صحيح"}]}
